805: function SecureActionButton_OnClick(self, inputButton, down, isKeyPress, isSecureAction)
806: 	-- Why are we adding extra arguments, 'isKeyPress' and 'isSecureAction', to an _OnClick handler?
807: 	-- We want to prevent mouse actions from triggering press-and-hold behavior for now, but we do want to allow AddOns
808: 	-- to function as they did before. This is a problem since there's no difference between an AddOn's key press behavior
809: 	-- and mouse click behavior. So if we don't know where this is coming from, it's from an AddOn and should be treated as
810: 	-- a key press not a mouse press for 'useOnKeyDown' purposes.
811: 	local isSecureMousePress = not isKeyPress and isSecureAction;
812: 	local pressAndHoldAction = SecureButton_GetAttribute(self, "pressAndHoldAction");
813: 	local useOnKeyDown = not isSecureMousePress and (SecureActionButton_ShouldUseOnKeyDown(self) or pressAndHoldAction);
814: 	local clickAction = (down and useOnKeyDown) or (not down and not useOnKeyDown);
815: 	local releasePressAndHoldAction = (not down) and (pressAndHoldAction or GetCVarBool("ActionButtonUseKeyHeldSpell"));
816: 
817: 	if clickAction then
818: 		-- Only treat a key down action as a key press. Treating key up actions as a key press will result in the held
819: 		-- spell being cast indefinitely since there's no release to stop it.
820: 		local treatAsKeyPress = down and isKeyPress;
821: 		OnActionButtonClick(self, inputButton, down, treatAsKeyPress);
822: 		return true;
823: 	elseif releasePressAndHoldAction then
824: 		OnActionButtonPressAndHoldRelease(self, inputButton);
825: 		return true;
826: 	end
827: 
828: 	return false;
829: end

109: function TryUseActionButton(self, checkingFromDown)
110: 	local isKeyPress = true;
111: 	local isSecureAction = true;
112: 	local usedActionButton = SecureActionButton_OnClick(self, "LeftButton", checkingFromDown, isKeyPress, isSecureAction);
113: 	if usedActionButton then
