795: function SecureActionButton_ShouldUseOnKeyDown(self)
796: 	local useOnKeyDown = SecureButton_GetAttribute(self, "useOnKeyDown");
797: 
798: 	if useOnKeyDown == nil then
799: 		useOnKeyDown = GetCVarBool("ActionButtonUseKeyDown");
800: 	end
801: 
802: 	return useOnKeyDown;
803: end

