107: function SecureHandler_StateOnAttributeChanged(self, name, value)
108: 	local stateid = name:match("^state%-(.+)");
109: 	if (stateid) then
110: 		local body = self:GetAttribute("_onstate-" .. stateid);
111: 		if (body) then
112: 			SecureHandler_Self_Execute(self, "self,stateid,newstate", body, stateid, value);
113: 		end
114: 	end
115: end

